declare(strict_types=1);$root=dirname(__DIR__);require_once $root.'/scripts/lib/n1-certification-session.php';$create=in_array('--create',$argv,true)||in_array('--ensure',$argv,true);$finalize=in_array('--finalize',$argv,true);try{if($finalize){$data=nexoraFinalizeCertificationSession($root);fwrite(STDOUT,json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR).PHP_EOL);exit(0);}$data=$create?nexoraEnsureCertificationSession($root):nexoraCertificationSessionRead($root);if(!is_array($data)){fwrite(STDERR,"[N1.0 Session] No certification session exists.\n");exit(2);}$errors=nexoraValidateCertificationSession($root,$data);if($errors!==[]){fwrite(STDERR,"[N1.0 Session] FAIL\n - ".implode("\n - ",$errors)."\n");exit(1);}$final=nexoraCertificationSessionFinalizationRead($root);$data['finalization_status']=is_array($final)&&nexoraValidateCertificationSessionFinalization($root,$final)===[]?'finalized':'open';fwrite(STDOUT,json_encode($data,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR).PHP_EOL);exit(0);}catch(Throwable $e){fwrite(STDERR,"[N1.0 Session] FAIL — {$e->getMessage()}\n");exit(1);}
